def version_tuple(text):
    parts = text.split(".")
    if any(not p or any(c not in "0123456789" for c in p) for p in parts):
        raise ValueError("version")
    values = list(map(int, parts))
    while len(values) > 1 and values[-1] == 0:
        values.pop()
    return tuple(values)

